    }

    @Test
    void createsReservationForCompanyWithCnpj() throws Exception {
        String companyReservation = """
                {"roomNumber": 201, "guestName": "Ana Souza", "guestEmail": "ana@example.com",
                 "companyCnpj": "12.345.678/0001-90", "companyName": "Tecnosul Ltda",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12",
                 "guests": 2, "ratePlan": "STANDARD"}
                """;

        HttpResponse<String> created = post("/reservations", companyReservation);
        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        long id = reservation.get("id").asLong();
        assertEquals("12.345.678/0001-90", reservation.get("companyCnpj").asText());
        assertEquals("Tecnosul Ltda", reservation.get("companyName").asText());
        assertTrue(reservation.get("guestCpf").isNull());
        assertTrue(reservation.get("guestPassport").isNull());

        post("/reservations/" + id + "/confirmation", "");
        post("/reservations/" + id + "/check-in", "");
        HttpResponse<String> checkedOut = post("/reservations/" + id + "/check-out", "");
        JsonNode document = json.readTree(checkedOut.body());
        assertEquals("Fatura de hospedagem", document.get("title").asText());
        assertTrue(document.get("text").asText().contains("Empresa: Tecnosul Ltda"));
        assertTrue(document.get("text").asText().contains("CNPJ 12.345.678/0001-90"));
        assertTrue(document.get("text").asText().contains("ISS retido (5%)"));
    }

    @Test
    void createsReservationForForeignGuestWithPassport() throws Exception {
        String foreignReservation = """
                {"roomNumber": 201, "guestName": "John Smith", "guestEmail": "john@example.com",
                 "guestPassport": "X1234567", "guestCountry": "United Kingdom",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12",
                 "guests": 2, "ratePlan": "STANDARD"}
                """;

        HttpResponse<String> created = post("/reservations", foreignReservation);
        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        long id = reservation.get("id").asLong();
        assertEquals("X1234567", reservation.get("guestPassport").asText());
        assertEquals("United Kingdom", reservation.get("guestCountry").asText());
        assertTrue(reservation.get("guestCpf").isNull());
        assertTrue(reservation.get("companyCnpj").isNull());

        post("/reservations/" + id + "/confirmation", "");
        post("/reservations/" + id + "/check-in", "");
        HttpResponse<String> checkedOut = post("/reservations/" + id + "/check-out", "");
        JsonNode document = json.readTree(checkedOut.body());
        assertEquals("Booking receipt", document.get("title").asText());
        assertTrue(document.get("text").asText().contains("Guest: John Smith"));
        assertTrue(document.get("text").asText().contains("passport X1234567"));
        assertTrue(document.get("text").asText().contains("United Kingdom"));
        assertTrue(document.get("text").asText().contains("2027-03-10"));
        assertTrue(document.get("text").asText().contains("BRL "));
    }

    @Test
    void requiresExactlyOneIdentificationType() throws Exception {
        String noIdentification = """
                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "checkIn": "2027-07-10", "checkOut": "2027-07-12",
                 "guests": 2, "ratePlan": "STANDARD"}
                """;
        HttpResponse<String> response1 = post("/reservations", noIdentification);
        assertEquals(400, response1.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(response1.body()).get("error").asText());

        String bothCpfAndCnpj = """
                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "guestCpf": "111.222.333-44", "companyCnpj": "12.345.678/0001-90", "companyName": "Empresa",
                 "checkIn": "2027-07-10", "checkOut": "2027-07-12",
                 "guests": 2, "ratePlan": "STANDARD"}
                """;
        HttpResponse<String> response2 = post("/reservations", bothCpfAndCnpj);
        assertEquals(400, response2.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(response2.body()).get("error").asText());

        String cnpjWithoutCompanyName = """
                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "companyCnpj": "12.345.678/0001-90",
                 "checkIn": "2027-07-10", "checkOut": "2027-07-12",
                 "guests": 2, "ratePlan": "STANDARD"}
                """;
        HttpResponse<String> response3 = post("/reservations", cnpjWithoutCompanyName);
        assertEquals(400, response3.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(response3.body()).get("error").asText());
    }
}

