import java.math.BigDecimal;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;

class DocumentGenerationTest {

    @Test
    void generatesReceiptForIndividualWithCpf() {
        Guest guest = new Guest("Maria Silva", "maria@example.com", "123.456.789-00", null, null, null, null);
        NewReservation request = new NewReservation(
                201, guest, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 2, RatePlan.STANDARD);
        Price price = new Price(2, new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"));
        Reservation reservation = new Reservation(1L, request, price);
        Room room = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));

        ReservationDocument document = ReservationDocument.from(reservation, room);

        assertTrue(document.text().contains("Comprovante de reserva nº 1"));
        assertTrue(document.text().contains("Hóspede: Maria Silva (CPF 123.456.789-00)"));
        assertTrue(document.text().contains("Quarto: 201 (DELUXE)"));
        assertTrue(document.text().contains("2 diárias"));
        assertTrue(document.text().contains("R$ 779,80"));
        System.out.println("=== Comprovante (CPF) ===");
        System.out.println(document.text());
    }

    @Test
    void generatesInvoiceForCompanyWithCnpj() {
        Guest guest = new Guest(
                "Ana Souza", "ana@example.com", null, "12.345.678/0001-90", "Tecnosul Ltda", null, null);
        NewReservation request = new NewReservation(
                201, guest, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 2, RatePlan.STANDARD);
        Price price = new Price(2, new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"));
        Reservation reservation = new Reservation(3L, request, price);
        Room room = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));

        ReservationDocument document = ReservationDocument.from(reservation, room);

        assertTrue(document.text().contains("Fatura de hospedagem nº 3"));
        assertTrue(document.text().contains("Empresa: Tecnosul Ltda (CNPJ 12.345.678/0001-90)"));
        assertTrue(document.text().contains("Hóspede: Ana Souza"));
        assertTrue(document.text().contains("ISS retido (5%): R$ 38,99"));
        System.out.println("=== Fatura de hospedagem (CNPJ) ===");
        System.out.println(document.text());
    }

    @Test
    void generatesInternationalReceiptForForeignGuest() {
        Guest guest = new Guest(
                "John Smith", "john@example.com", null, null, null, "X1234567", "United Kingdom");
        NewReservation request = new NewReservation(
                201, guest, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 2, RatePlan.STANDARD);
