        assertTrue(document.text().contains("Guest: John Smith (passport X1234567, United Kingdom)"));
        assertTrue(document.text().contains("2027-03-10"));
        assertTrue(document.text().contains("2027-03-12"));
        assertTrue(document.text().contains("2 nights"));
        assertTrue(document.text().contains("BRL 779.80"));
        System.out.println("=== Booking receipt (Passaporte) ===");
        System.out.println(document.text());
    }

    @Test
    void generatesReceiptWithDiscountAndSingleNight() {
        Guest guest = new Guest(
                "John Smith", "john@example.com", null, null, null, "X1234567", "United Kingdom");
        NewReservation request = new NewReservation(
                201, guest, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-11"), 1, RatePlan.NON_REFUNDABLE);
        Price price = new Price(1, new BigDecimal("389.90"), new BigDecimal("58.48"), new BigDecimal("331.42"));
        Reservation reservation = new Reservation(5L, request, price);
        Room room = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));

        ReservationDocument document = ReservationDocument.from(reservation, room);

        assertTrue(document.text().contains("1 night"));
        assertTrue(document.text().contains("Discount: BRL 58.48"));
        assertTrue(document.text().contains("Total: BRL 331.42"));
        System.out.println("=== Booking receipt (com desconto, 1 night) ===");
        System.out.println(document.text());
    }
}

